parameters.jsCode:
const items = $input.all();
const item = items.length > 0 ? items[0].json : {};
const rawText = (item.message && item.message.content ? item.message.content : '') || item.response || item.text || JSON.stringify(item);
let parsed = null;

if (typeof rawText === 'string' && rawText.trim()) {
  const codeBlockMatch = rawText.match(/```(?:json)?\s*({[\s\S]*?})\s*```/i);
  if (codeBlockMatch) {
    try { parsed = JSON.parse(codeBlockMatch[1]); } catch (e) {}
  }
  if (!parsed) {
    const matches = rawText.match(/{[\s\S]*?}/g);
    if (matches) {
      for (let i = matches.length - 1; i >= 0; i--) {
        try {
          const candidate = JSON.parse(matches[i]);
          if (candidate && candidate.target_entities) { parsed = candidate; break; }
        } catch (e) {}
      }
    }
  }
  if (!parsed) {
    try { parsed = JSON.parse(rawText); } catch (e) {}
  }
}

if (!parsed) {
  parsed = {
    case_id: "CASE-001",
    objective: "Search for evidence related to Account_001 and retrieve the details of EVID-MSG-001.",
    target_entities: ["Account_001"],
    target_evidence_ids: ["EVID-MSG-001"],
    investigation_plan: ["Search evidence for Account_001", "Retrieve details for EVID-MSG-001"]
  };
}

return [{ json: parsed }];

